url') value = ''\n        formData.append(`gallery[${index}][${fieldName}]`, value);\n      })\n    });\n    createRequestWithFormData(POST_GALLERY_URL(clinicId.value), {'Accept': 'application/json'}, formData).then((res) => reset_close_offcanvas(res));\n  }\n\n  </script>\n\n  <style scoped>\n  .gallery-images {\n    display: grid;\n      grid-template-columns: repeat(auto-fill, minmax(104px, 1fr));\n      grid-gap: 1rem;\n      align-items: stretch;\n  }\n  .image-container {\n    position: relative;\n    max-width: 100%;\n  }\n\n  .delete-button {\n    position: absolute;\n    top: -8px;\n    right: -8px;\n    z-index: 1;\n    color: var(--bs-white);\n    background-color: var(--bs-danger);\n    border: none;\n    border-radius: 50%;\n    width: 24px;\n    height: 24px;\n    font-size: 14px;\n    display: flex;\n    align-items: center;\n    justify-content: center;\n  }\n\n  .selected-image {\n    object-fit: cover;\n    height: 100px;\n    width: 100%;\n  }\n  .uppy-Dashboard-progressindicators{\n  display: none;\n}\n  </style>\n"],"sourceRoot":""}]);
